(()=>{'use strict';
const D=window.PEL_DATA;const STORE='pel-student-v1';const ROUTES=[['home','⌂','Home'],['lessons','▤','Lessons'],['discover','✧','Discover'],['lab','▣','Laboratory'],['coach','✺','No inspiration?'],['field','⌁','Fieldwork'],['exam','◈','Challenges'],['progress','▥','Progress'],['journal','▤','Journal'],['settings','⚙','Settings']];const MOBILE=['home','lessons','discover','lab','field','progress'];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));const today=()=>new Date().toISOString();const date=s=>{try{return new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}catch{return s}};const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));const A=s=>Array.isArray(s)?s:[];const btn=(text,action,extra='',cls='btn')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const blank=()=>({version:1,done:[],found:{},journal:[],studies:[],fieldLogs:[],fieldChecks:{},notes:{},exams:[],examSession:null,coachDone:[],photo:null,created:today()});let state=blank();try{let p=JSON.parse(localStorage.getItem(STORE)||'null');if(p&&p.version===1&&Array.isArray(p.done)&&Array.isArray(p.journal))state={...blank(),...p};}catch{};
let route='home',lessonId='seeing',sceneIndex=0,hotIndex=-1,labScene=0,labCrop={x:.14,y:.14,w:.72,h:.72},labRatio='3:2',labGrid=true,labImage=null,labDrag=null,labImgSrc='',labReport=null,activeField='hw15',coachStep=0,coachAnswers={},quizPage=0,quizAnswered=false,quizSelected=-1,menuOpen=false;
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));return true}catch(e){toast('Local storage is full. Export your progress or remove a saved practice photo.');return false}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>t.classList.remove('show'),3700)}
function nav(to){location.hash=to;let same=route===to;route=to;render();if(same)window.scrollTo({top:0,behavior:'smooth'});}
function renderNavigation(){const make=(r)=>`<button type="button" class="nav-link ${route===r[0]?'active':''}" data-route="${r[0]}"><span class="nav-ico">${r[1]}</span><span>${r[2]}</span>${r[0]==='lessons'?`<small>${state.done.length}/${D.lessons.length}</small>`:''}</button>`;$('#side-nav').innerHTML=ROUTES.map(make).join('');$('#mobile-tabs').innerHTML=MOBILE.map(id=>{let r=ROUTES.find(x=>x[0]===id);return `<button type="button" data-route="${id}" class="${route===id?'active':''}">${r[1]}<small>${r[2]}</small></button>`}).join('');$('#sidebar').classList.toggle('open',menuOpen);$('#top-title').textContent=route==='home'?'Your photographic eye':ROUTES.find(x=>x[0]===route)?.[2]||'Photographic Eye Lab';}
function progress(){const l=state.done.length,hot=Object.values(state.found||{}).reduce((a,b)=>a+A(b).length,0),totalHot=D.scenes.reduce((n,s)=>n+s.hotspots.length,0);return {l,hot,totalHot,field:state.fieldLogs.length,studies:state.studies.length,exams:state.exams.length};}
function head(title,sub,tag='THE LEARNING SPACE',actions=''){return `<div class="head-panel"><div><div class="section-kicker">${tag}</div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="btn-row">${actions}</div>`:''}</div>`}
function cardLesson(l){const d=state.done.includes(l.id);return `<article class="lesson-card" data-route="lesson/${l.id}" role="button" tabindex="0"><div class="btn-row" style="justify-content:space-between"><span class="lesson-no">${l.n}</span><span class="pill ${d?'green':''}">${d?'✓ Completed':l.mins+' min'}</span></div><h3>${esc(l.title)}</h3><p>${esc(l.strap)}</p><span class="page-meta">${esc(l.skill)} →</span></article>`}
function cardScene(s){return `<article class="feature-card" data-scene="${s.n-1}" role="button" tabindex="0"><div class="photo" style="background-image:url('${s.image}')"></div><div class="feature-info"><span class="tag">SCENE ${String(s.n).padStart(2,'0')}</span><strong>${esc(s.title)}</strong><p>${esc(s.subtitle)}</p></div></article>`}
function home(){let next=D.lessons.find(l=>!state.done.includes(l.id))||D.lessons[0],p=progress();return `<section class="hero" style="background-image:url('scenes/scene-2.jpg')"><div class="hero-content"><div class="eyebrow">TRAIN YOUR PHOTOGRAPHIC EYE</div><h1>Turn ordinary places into interesting photographs.</h1><p>You're good at seeing geometry. Now train yourself to notice the subject, light, relationships and moments that make a picture.</p><div class="btn-row">${btn('✦ I can’t find a picture','open-coach')}${btn('Open the laboratory →','open-lab','','btn secondary')}</div></div></section>
<div class="grid grid-4 mt20"><div class="mini-stat"><div class="value">${p.l}<small> / ${D.lessons.length}</small></div><small>Lessons completed</small></div><div class="mini-stat"><div class="value">${p.hot}<small> / ${p.totalHot}</small></div><small>Scene discoveries</small></div><div class="mini-stat"><div class="value">${p.studies}</div><small>Compositions studied</small></div><div class="mini-stat"><div class="value">${p.field}</div><small>Field sessions logged</small></div></div>
<div class="section-head"><h2>Start with seeing</h2><button type="button" class="muted-link" data-route="lessons">Explore all nine lessons →</button></div><div class="grid grid-3">${D.lessons.slice(0,3).map(l=>`<article class="feature-card" data-route="lesson/${l.id}" role="button" tabindex="0"><div class="photo" style="background-image:url('${D.scenes[l.scene-1].image}')"></div><div class="feature-info"><span class="tag">LESSON ${l.n} · ${l.mins} MIN</span><strong>${esc(l.title)}</strong><p>${esc(l.strap)}</p></div></article>`).join('')}</div>
<div class="grid grid-2 mt20"><section class="panel"><div class="section-kicker">THE PRACTICAL LABORATORY</div><h2>Build the frame yourself</h2><p class="small muted">Choose a photograph, drag the crop, change framing, then explain what you kept and what you removed. See structural feedback—not a false artistic “correct answer”.</p><div style="background:url('scenes/scene-3.jpg') center/cover;height:168px;border-radius:10px;position:relative;margin-bottom:15px;overflow:hidden"><div style="position:absolute;inset:12% 19%;border:2px solid white;box-shadow:0 0 0 90px #02090b66"><div style="position:absolute;inset:0;border-left:1px solid #ffffff66;border-right:1px solid #ffffff66;width:33.33%;margin-left:33.33%"></div></div></div>${btn('Open crop laboratory →','open-lab','','btn sm')}</section>
<section class="panel"><div class="section-kicker">TODAY’S FIELD MISSION</div><h2>${esc(D.fields[0].title)}</h2><p class="small muted">${esc(D.fields[0].brief)}</p><div class="floating-tip"><h3>Before you raise the camera</h3><p class="mb0 small">“The photograph is…”. If you cannot finish the sentence, keep looking for light, separation or a relationship.</p></div><div class="btn-row mt20">${btn('Start Harold Wood Park drill','field-start',`data-id="hw15"`,'btn sm')}${btn('No inspiration?','open-coach','','btn secondary sm')}</div></section></div>
<div class="section-head"><h2>Practice with scenes</h2><button type="button" class="muted-link" data-route="discover">Find more possibilities →</button></div><div class="grid grid-4">${D.scenes.map(cardScene).join('')}</div>`}
function lessons(){return `${head('Learn to see','Nine guided chapters designed around the gap between recording a place accurately and recognising an image worth making. Each ends with a real shooting assignment.','STRUCTURED COURSE',btn('Start next lesson →','lesson-open',`data-id="${(D.lessons.find(l=>!state.done.includes(l.id))||D.lessons[0]).id}"`,'btn sm'))}<div class="lesson-grid">${D.lessons.map(cardLesson).join('')}</div><section class="note mt20"><strong>How to study:</strong> learn one principle, test it outdoors, compare at least two actual frames and explain the difference. Reading alone doesn't count as training.</section>`}
function lesson(l){if(!l)l=D.lessons[0];return `<button type="button" class="back-link" data-route="lessons">← All lessons</button><div class="lesson-hero"><div class="lesson-photo" style="background-image:url('${D.scenes[l.scene-1].image}')"></div><div class="lesson-intro"><div class="eyebrow">CHAPTER ${l.n} · ${l.mins} MIN</div><h2>${esc(l.title)}</h2><p>${esc(l.lead)}</p><span class="pill">${esc(l.skill)} · Guided study</span></div></div><div class="section-head"><h2>Principles to practise</h2><small>Study the reasons, not just the rules</small></div><div class="principles">${l.principles.map((pr,i)=>`<div class="principle"><span class="index">${String(i+1).padStart(2,'0')}</span><h3>${esc(pr[0])}</h3><p>${esc(pr[1])}</p></div>`).join('')}</div><section class="exercise-box"><div class="section-kicker">FIELD ASSIGNMENT</div><h3>Apply this outside</h3><p>${esc(l.drill)}</p></section><div class="grid grid-2 mt20"><div class="panel"><h3>Common trap</h3><p class="small muted">${esc(l.pitfall)}</p><div class="divider"></div><h3>Visual self-check</h3><p class="small muted">${esc(l.check)}</p></div><div class="panel"><h3>Think before you shoot</h3><p class="small muted">${esc(l.micro)}</p><div class="divider"></div><label class="field"><span>My observation or planned test</span><textarea id="lesson-note" maxlength="3000" placeholder="What would I look for or change?">${esc(state.notes[l.id]||'')}</textarea></label></div></div><div class="btn-row mt20">${btn('Save my note','save-lesson-note',`data-id="${l.id}"`,'btn secondary')}${btn(state.done.includes(l.id)?'✓ Lesson studied':'Mark lesson studied','complete-lesson',`data-id="${l.id}"`)}${btn('Practise this scene →','lesson-scene',`data-n="${l.scene-1}"`,'btn secondary')}</div><div class="note small">Completion records that you studied the chapter. Your photographic improvement is evaluated through actual exercises and comparisons, not the completion tick.</div>`}
function discover(){let s=D.scenes[sceneIndex],found=A(state.found[s.id]),h=s.hotspots[hotIndex];return `${head('Discover the picture','Look at a normal scene and practise locating possible subjects. Tap a point to reveal a photographic reading; alternatives are possibilities, not uniquely correct answers.','INTERACTIVE SCENE FINDER',btn('Use guided discovery →','open-coach','','btn secondary sm'))}<div class="scene-picker">${D.scenes.map((x,i)=>`<button class="scene-tab ${sceneIndex===i?'active':''}" type="button" data-scene="${i}">${i+1} · ${esc(x.title)}</button>`).join('')}</div><div class="scene-banner"><div class="picture" style="background-image:url('${s.image}')"></div><div class="scene-summary"><span class="eyebrow">SCENE ${s.n} OF ${D.scenes.length}</span><h2>${esc(s.title)}</h2><p>${esc(s.summary)}</p><div class="pill gold">${found.length} / ${s.hotspots.length} interpretations explored</div><p class="mt20">Observe first: which part caught your eye—and why? Only then examine the marked ideas.</p></div></div><div class="grid grid-2 mt20"><div><div class="scene-map" aria-label="Interactive scene with candidate photographic points"><img src="${s.image}" alt="Training photograph: ${esc(s.title)}" draggable="false" />${s.hotspots.map((v,i)=>`<button type="button" class="hotspot ${hotIndex===i?'open':''} ${!found.includes(i)?'hidden-point':''}" style="left:${v.x}%;top:${v.y}%" data-hot="${i}" title="Explore this photographic possibility" aria-label="Photographic possibility ${i+1}">${found.includes(i)?'✓':'+'}</button>`).join('')}</div><p class="photo-label">Practice image: AI-generated illustrative park scene, not a photograph of Harold Wood Park. Tap a faint marker to explore a potential interpretation.</p></div><div class="reveal-card">${h?`<div class="section-kicker">A POSSIBLE PHOTOGRAPH · ${hotIndex+1} OF ${s.hotspots.length}</div><h3>${esc(h.title)}</h3><p>${esc(h.insight)}</p><div class="feedback-key"><strong>Test this:</strong> ${esc(h.move)}</div>${btn('Compose this scene →','lab-scene',`data-n="${sceneIndex}"`,'btn sm')}`:`<div class="section-kicker">YOUR EYE FIRST</div><h3>What attracts you in this scene?</h3><p>Before revealing any idea, say aloud “The photograph is…” and name one thing that makes it worth looking at: light, shape, isolation, a relationship or a moment.</p><div class="note"><strong>Not every marked point will produce a great picture.</strong> These are hypotheses to explore with a camera station, not an automatic answer key.</div>`}<div class="divider"></div><p class="tiny muted">Try all ${s.hotspots.length} points, then move to the Laboratory and frame an interpretation yourself.</p></div></div><div class="btn-row mt20">${btn('Previous scene','scene-prev','','btn secondary sm')}${btn('Next scene →','scene-next','','btn sm')}${btn('Add my own interpretation','write-scene-note','','btn secondary sm')}</div>`}
function lab(){return `${head('Composition laboratory','Explore the photographic decisions, not just the crop: choose your subject, remove distractions, and explain why your frame works. Drag the frame; use the controls to adjust it.','HANDS-ON VISUAL TRAINING')}<div class="lab-layout"><div class="flow-col"><div class="panel"><div class="section-head" style="margin:0 0 12px"><h3>Work the frame</h3><small>Pointer drag / touch drag / keyboard controls</small></div><div class="canvas-shell"><div class="canvas-wrap"><canvas id="crop-canvas" width="960" height="640" role="img" aria-label="Interactive crop framing over a park photograph"></canvas></div><div class="canvas-help">Drag inside the white frame to move it. Change zoom to adjust its size. The image outside the frame is deliberately darkened.</div></div><div class="btn-row mt12">${btn('←','lab-left','','btn secondary sm')}${btn('↑','lab-up','','btn secondary sm')}${btn('↓','lab-down','','btn secondary sm')}${btn('→','lab-right','','btn secondary sm')}${btn(labGrid?'▦ Grid on':'▦ Grid off','lab-grid','','btn secondary sm')}${btn('Reset','lab-reset','','btn secondary sm')}</div></div><div class="panel"><h3>Choose a subject and intention</h3><p class="small muted">A good crop is not defined by a rule of thirds. It is defined by what you want the viewer to notice and what you deliberately omit.</p><label class="field"><span>“The photograph is…”</span><input id="lab-subject" maxlength="180" placeholder="e.g. sunlight picking out one tree" value="${esc(labReport?.subject||'')}" /></label><label class="field"><span>Why is it worth looking at?</span><textarea id="lab-why" maxlength="700" placeholder="Light, isolation, line, relationship, colour, gesture…">${esc(labReport?.why||'')}</textarea></label><label class="field"><span>What did you deliberately leave out?</span><textarea id="lab-exclude" maxlength="700" placeholder="e.g. the large dark trunk at the edge">${esc(labReport?.excluded||'')}</textarea></label><div class="btn-row">${btn('Assess my composition','lab-assess')}${btn('Save this study','lab-save','','btn secondary')}${btn('Export cropped JPG','lab-export','','btn secondary')}</div><div id="lab-assessment">${labReport?.assessment||''}</div></div></div><div class="flow-col"><div class="panel"><h3>Source image</h3><p class="small muted">Choose one of four practice scenes, or use your own a6700 photograph.</p><div class="grid grid-2">${D.scenes.map((s,i)=>`<button data-lab-scene="${i}" type="button" style="padding:0;border:3px solid ${labScene===i?'#2878d2':'transparent'};background:none;border-radius:9px;overflow:hidden;position:relative"><img src="${s.image}" alt="${esc(s.title)}" style="width:100%;height:84px;object-fit:cover;display:block"><span style="display:block;background:#eff3f7;padding:4px;font-size:10px;color:#3f566c">Scene ${i+1}</span></button>`).join('')}</div><label class="field"><span>Use your own photograph · stays on this device</span><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" /><small>Uploaded only into this browser, never to a server. HEIC display depends on browser support.</small></label>${state.photo?`<div class="btn-row">${btn('Use saved photo','lab-own','','btn secondary sm')}${btn('Delete saved photo','lab-photo-remove','','btn secondary sm')}</div>`:''}</div><div class="panel"><h3>Framing controls</h3><div class="control"><label for="lab-zoom"><span>Crop zoom</span><output id="lab-zoom-value">${(1/labCrop.w).toFixed(2)}×</output></label><input type="range" id="lab-zoom" min="1.05" max="3.5" step="0.05" value="${(1/labCrop.w).toFixed(2)}" /></div><div class="control"><label>Aspect ratio</label><div class="seg">${['3:2','4:5','1:1','16:9'].map(s=>`<button data-ratio="${s}" type="button" class="${labRatio===s?'active':''}">${s}</button>`).join('')}</div></div><div class="note"><strong>Move before you crop in the field.</strong><p class="small mb0">Cropping on a fixed photograph cannot teach real viewpoint changes. Try this composition virtually, then test new camera positions outside. A different station changes geometry; zoom alone does not.</p></div></div><div class="quick-panel"><h3>Coach’s checklist</h3><div class="small">1 · One identifiable subject<br>2 · A specific reason to look<br>3 · Enough context, no surplus<br>4 · A deliberate camera position<br>5 · One alternative tested</div></div></div></div>`}
function coach(){const st=D.tips[coachStep];const done=coachStep>=D.tips.length;return `${head('No inspiration? Start here.','This is your field companion when everything looks like grass, trees, paths and geometry. Scan for visual opportunities in a fixed order. It is acceptable to decide that today has no worthwhile photograph.','GUIDED SCENE RECOVERY')}<div class="grid grid-2"><section class="panel"><div class="section-kicker">${done?'MAKE YOUR DECISION':`STEP ${coachStep+1} OF ${D.tips.length}`}</div><div class="step-progress">${D.tips.map((_,i)=>`<span class="${i<coachStep?'done':i===coachStep?'active':''}"></span>`).join('')}</div>${done?`<h2>Did you find a picture?</h2><p class="muted">Summarise the idea you identified, or record why the scene still lacks a subject/light relationship. Both outcomes build judgement.</p>`:`<div class="find-stage"><div class="stepnum">${coachStep+1}</div><h2 class="mb0">${esc(st[0])}</h2></div><p>${esc(st[1])}</p><div class="prompt-card"><h3>Say it out loud</h3><p>${coachStep===0?'“The light is doing something interesting on…”':coachStep===1?'“This line takes the eye toward…”':coachStep===2?'“That object separates clearly because…”':coachStep===3?'“The relationship is … + …”':coachStep===4?'“If I move my position, the background will…”':coachStep===5?'“The distraction I can remove is…”':coachStep===6?'“This scene may improve when…”':'“The photograph is…”'}</p></div>`}<label class="field"><span>${done?'My final observation':`What I found during this scan (optional)`}</span><textarea id="coach-entry" maxlength="2000" placeholder="One subject, relationship, light event or a reason this scan gave me nothing.">${esc(coachAnswers[coachStep]||'')}</textarea></label><div class="btn-row">${btn('← Previous','coach-prev',coachStep===0?'disabled':'','btn secondary sm')}${done?btn('Record this attempt','coach-finish'):btn('Next scan →','coach-next','','btn sm')}${btn('Restart','coach-reset','','btn secondary sm')}</div></section><section class="panel"><div class="section-kicker">THE FULL DISCOVERY SEQUENCE</div><h3>Eight steps for an ordinary place</h3>${D.tips.map((s,i)=>`<div class="bullet-feature"><strong style="color:${i===coachStep?'#1b6cc0':'#344e63'}">${i+1}. ${esc(s[0])}</strong><p>${esc(s[1])}</p></div>`).join('')}<div class="note"><strong>A good outcome isn't always a photograph.</strong><p class="small mb0">Recognising insufficient subject, timing or light—and knowing what to change—is a genuine skill.</p></div></section></div>`}
function field(){return `${head('Fieldwork & practice','Practical drills for Harold Wood Park, familiar streets and any ordinary location. Complete tasks with real-world evidence and record what you learned.','FIELD ASSIGNMENTS',btn('Help me find a scene','open-coach','','btn secondary sm'))}<div class="grid grid-3">${D.fields.map(f=>`<article class="assignment-card"><div class="btn-row" style="justify-content:space-between"><span class="pill ${f.level==='Foundation'?'green':f.level==='Advanced'?'gold':''}">${f.level}</span><span class="tiny muted">${f.duration}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.brief)}</p><div class="tiny muted">⌁ ${esc(f.place)}</div>${btn('Open field brief →','field-start',`data-id="${f.id}"`,'btn sm')}</article>`).join('')}</div>`}
function fieldDetail(f){let checks=A(state.fieldChecks[f.id]),notes=state.notes['field:'+f.id]||'',latest=A(state.fieldLogs).filter(x=>x.id===f.id).slice(-1)[0];return `<button type="button" class="back-link" data-route="field">← All field assignments</button>${head(esc(f.title),esc(f.objective),'FIELD SESSION · '+esc(f.level))}<div class="grid grid-2"><div class="panel"><span class="pill">⌁ ${esc(f.place)} · ${esc(f.duration)}</span><h2 class="mt20">Your brief</h2><p>${esc(f.brief)}</p><div class="note small"><strong>Suggested kit:</strong> ${esc(f.gear)}</div><h3 class="mt20">Mission steps</h3><div class="progress-bar"><span style="width:${Math.round(100*checks.length/f.steps.length)}%"></span></div>${f.steps.map((s,i)=>`<label class="checkline"><input type="checkbox" data-fieldcheck="${i}" data-fieldid="${f.id}" ${checks.includes(i)?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div><div class="flow-col"><div class="panel"><h3>Field notes</h3><p class="muted small">Record actual observations, including failures. Save a truthful session report; don’t mark a walk complete because you read the steps.</p><label class="field"><span>What was the photograph?</span><textarea id="field-notes" maxlength="2500" placeholder="Location, subject, light, camera station and what you excluded…">${esc(notes)}</textarea></label><div class="feedback-key"><strong>Success criterion:</strong> ${esc(f.success)}</div><div class="btn-row">${btn('Save notes','field-save',`data-id="${f.id}"`,'btn secondary')}${btn('Log completed field session','field-complete',`data-id="${f.id}"`)}</div>${latest?`<p class="tiny muted mt12">Last logged: ${date(latest.date)}</p>`:''}</div><div class="quick-panel"><h3>After the walk</h3><p>Don't show only your best picture. Keep the near misses and ask: Which frame has the clearest subject? What did moving or waiting actually change?</p>${btn('Open journal →','go-journal','','btn secondary sm')}</div></div></div>`}
function exam(){if(!state.examSession)return `${head('Composition decisions challenge','A 27-question scenario assessment covering subject recognition, light, composition, viewpoint and selection. These check reasoning; they are not a measure of artistic talent.','KNOWLEDGE & JUDGEMENT')}<div class="grid grid-2"><div class="panel"><div class="section-kicker">REAL-WORLD DECISIONS</div><h2>27 questions · five skills</h2><p>Each answer explains why a specific shooting decision is more defensible. No artificial formula for a beautiful photograph.</p>${btn('Begin challenge →','exam-start')}<p class="tiny muted mt12">Your answers are saved locally as you progress.</p></div><div class="panel"><h3>Previously completed</h3>${state.exams.length?state.exams.slice(-5).reverse().map(x=>`<div class="bullet-feature"><strong>${date(x.date)} · ${x.score}/${D.questions.length}</strong><p>Knowledge score; evaluate actual photographs separately.</p></div>`).join(''):`<p class="muted">No completed challenge yet.</p>`}</div></div>`;
let ses=state.examSession;let q=D.questions[ses.index];if(!q)return examDone(ses);let chose=ses.answers[q.id];let ans=Number.isInteger(chose);return `${head('Visual decision challenge','Select the strongest photographic reasoning and study the explanation. Some aesthetic outcomes remain subjective; these questions test practical principles.','QUESTION '+(ses.index+1)+' OF '+D.questions.length)}<div class="grid grid-2"><div class="panel"><span class="question-no">${q.skill.toUpperCase()} · ${ses.index+1} / ${D.questions.length}</span><div class="progress-bar mt12"><span style="width:${100*(ses.index+1)/D.questions.length}%"></span></div><h2 class="mt20">${esc(q.prompt)}</h2><div class="quiz-options">${q.options.map((o,i)=>`<button type="button" data-qanswer="${i}" class="quiz-option ${ans?(i===q.answer?'correct':i===chose?'wrong':''):''}" ${ans?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div>${ans?`<div class="quiz-feedback"><h3>${chose===q.answer?'✓ Sound reasoning':'Consider the alternative'}</h3><p>${esc(q.why)}</p></div><div class="btn-row mt20">${btn(ses.index===D.questions.length-1?'Finish & review':'Next question →','exam-next')}</div>`:`<p class="small muted">Think about what the camera station, light and visual intention are doing—not just camera settings.</p>`}</div><div class="panel"><div class="section-kicker">YOUR PRACTICAL TRANSLATION</div><h3>Make the answer observable</h3><p class="muted small">If this were Harold Wood Park, how would you test your answer with two frames?</p><label class="field"><span>Optional observation</span><textarea id="quiz-note" maxlength="800" placeholder="What would I physically change?">${esc(ses.notes?.[q.id]||'')}</textarea></label>${btn('Save observation','exam-note',`data-qid="${q.id}"`,'btn secondary sm')}<div class="note small"><strong>Reminder:</strong> A correct concept answer cannot prove that you can make a compelling image; the field exercises measure applied practice.</div></div></div>`}
function examDone(ses){let answers=ses.answers||{},correct=D.questions.filter(q=>answers[q.id]===q.answer).length;return `${head('Challenge complete','This measures photographic reasoning—not creative worth. Apply the weaker topics in an actual walk.','YOUR RESULTS')}<div class="grid grid-2"><div class="panel"><div class="score-star">${correct} / ${D.questions.length}</div><p class="small muted">Concept questions answered as intended</p><div class="progress-bar"><span style="width:${100*correct/D.questions.length}%"></span></div><div class="btn-row mt20">${btn('Save result','exam-finish')}${btn('Try another challenge','exam-restart','','btn secondary')}</div></div><div class="panel"><h3>By skill</h3>${D.skills.map(skill=>{let q=D.questions.filter(q=>q.skill===skill);let got=q.filter(x=>answers[x.id]===x.answer).length;return `<div class="skill-row"><div class="row-head"><span>${skill}</span><span>${got}/${q.length}</span></div><div class="progress-bar"><span style="width:${100*got/q.length}%"></span></div></div>`}).join('')}</div></div>`}
function progressPage(){let p=progress();return `${head('Your learning record','A transparent view of practice and reasoning. These counts show participation, not a numerical judgement of photographic vision.','PERSONAL PROGRESS',btn('Export my progress','export-data','','btn secondary sm'))}<div class="grid grid-4"><div class="mini-stat"><div class="value">${p.l}<small> / 9</small></div><small>Chapters studied</small></div><div class="mini-stat"><div class="value">${p.hot}<small> / 20</small></div><small>Photo readings explored</small></div><div class="mini-stat"><div class="value">${p.studies}</div><small>Crop studies with intent</small></div><div class="mini-stat"><div class="value">${p.field}</div><small>Field reports</small></div></div><div class="grid grid-2 mt20"><div class="panel"><h2>Course progress</h2>${D.lessons.map(l=>`<div class="bullet-feature" style="display:flex;justify-content:space-between;gap:9px"><span class="small">${l.n}. ${esc(l.title)}</span><span class="pill ${state.done.includes(l.id)?'green':''}">${state.done.includes(l.id)?'Studied':'Not yet'}</span></div>`).join('')}</div><div class="panel"><h2>Reasoning by skill</h2>${D.skills.map(skill=>{let answers=state.exams.slice(-1)[0]?.answers||{};let questions=D.questions.filter(q=>q.skill===skill);let count=questions.filter(q=>answers[q.id]===q.answer).length;let total=questions.length;return `<div class="skill-row"><div class="row-head"><span>${skill}</span><span>${state.exams.length?`${count}/${total}`:'Not assessed'}</span></div><div class="progress-bar"><span style="width:${state.exams.length?100*count/total:0}%"></span></div></div>`}).join('')}<div class="divider"></div><h3>Practice evidence</h3><p class="small muted">${state.coachDone.length} scene recovery attempts · ${state.journal.length} journal entries · ${state.studies.length} framing studies · ${state.exams.length} completed knowledge challenges</p><div class="note small">An excellent photograph can break several conventional composition rules. The progress indicators never claim to grade artistry.</div></div></div>`}
function journal(){return `${head('Observation journal','Make the thought visible: what caught your eye, why it mattered and what you changed. Save near misses, not just favourites.','FIELD NOTEBOOK',btn('New journal entry','journal-new'))}<div class="grid grid-2"><div class="panel"><h2>Your recent observations</h2>${state.journal.length?state.journal.slice().reverse().map(x=>`<article class="journal-entry"><div class="entry-title"><h3>${esc(x.title||'Field observation')}</h3><button type="button" class="muted-link" data-journal-delete="${x.id}">Delete</button></div><time>${date(x.date)} · ${esc(x.type||'Journal')}</time><p style="white-space:pre-wrap">${esc(x.body)}</p></article>`).join(''):`<div class="empty"><span class="symbol">✎</span><strong>No field observations yet</strong><span>Start with a small visual relationship, not a perfect photograph.</span></div>`}</div><div class="flow-col"><div class="panel"><h3>Composition studies</h3>${state.studies.length?state.studies.slice().reverse().slice(0,12).map(x=>`<div class="bullet-feature"><strong>${esc(x.subject)} · ${date(x.date)}</strong><p>${esc(x.why||'No written reason')}</p><p><strong>Excluded:</strong> ${esc(x.excluded||'Not recorded')}</p></div>`).join(''):`<p class="muted small">Saved crop experiments appear here.</p>`}</div><div class="panel"><h3>Completed field sessions</h3>${state.fieldLogs.length?state.fieldLogs.slice().reverse().map(x=>`<div class="bullet-feature"><strong>${esc((D.fields.find(f=>f.id===x.id)||{}).title||x.id)}</strong><p>${date(x.date)} · ${esc(x.notes)}</p></div>`).join(''):`<p class="muted small">Field observations are logged from their assignments.</p>`}</div></div></div>`}
function settings(){return `${head('Settings & your data','Everything in this application is kept in your browser on this device. There is no account, analytics, sync server or image upload service.','OFFLINE & PRIVACY')}<div class="grid grid-2"><div class="panel"><h2>Offline use</h2><p>After installing or opening the site once online, the entire course, practice images and learning tools are cached for offline use. The offline status indicator shows whether the app has prepared its assets.</p><div id="settings-offline" class="note small">${navigator.serviceWorker?'Offline support available on this browser.':'Open via HTTPS in a supported browser for installable offline mode.'}</div><div class="btn-row mt20">${btn('Check offline cache','offline-check','','btn secondary sm')}${btn('Refresh offline assets','offline-update','','btn secondary sm')}</div><h3 class="mt20">Install on your device</h3><p class="small muted"><strong>iPhone:</strong> Safari → Share → Add to Home Screen; open once online. <strong>Android:</strong> Chrome → Install / Add to Home Screen. <strong>Desktop:</strong> use the browser's install option. The standalone HTML ZIP works directly from a desktop browser without internet.</p></div><div class="panel"><h2>Backup & transfer</h2><p>Your learning record is saved locally. Different browsers/devices do not sync. Export JSON to move records elsewhere; import replaces the current local record.</p><div class="btn-row">${btn('Export progress JSON','export-data')}${btn('Import backup JSON','import-file','','btn secondary')}</div><input type="file" id="backup-file" accept=".json,application/json" hidden><div class="divider"></div><h3>Erase this device's record</h3><p class="small muted">Removes notes, lesson progress, practice photos and session records in this browser only. It does not affect any other device.</p>${btn('Clear local progress','clear-data','','btn warn sm')}</div></div><div class="panel mt20"><div class="section-kicker">ABOUT THIS COURSE</div><h2>Editorial sources & integrity</h2><p class="small muted">This is an independently authored training course. The teaching areas are informed by the broader study of visual composition, photographic creativity and photographic intention, including these recommended books. Their copyrighted text, figures, exercises and photographs have not been reproduced or represented as consulted in full.</p><div class="reference"><div><span class="ref-title">Michael Freeman</span><p><em>The Photographer’s Eye: Definitive Edition</em> (2025). Visual organisation, viewpoint and eye movement.</p></div><div><span class="ref-title">Bryan Peterson</span><p><em>Learning to See Creatively</em>. Discovering subjects and alternatives.</p></div><div><span class="ref-title">David duChemin</span><p><em>Within the Frame</em>. Personal vision, intent and meaningful images.</p></div><div><span class="ref-title">GD Lab philosophy</span><p>Understand → Explore → Practise → Test → Record progress. Separate application; no GD Lab assets or files changed.</p></div></div><div class="note small">The four built-in practice scenes are AI-generated illustrations of ordinary park photography. They are not labelled as photographs of any named place, and their hotspots show reasoned possibilities rather than artistic ground truth.</div></div>`}
function modal(title,body){$('#modal').innerHTML=`<div class="modal-box" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button type="button" data-action="modal-close" aria-label="Close dialog">×</button></div>${body}</div>`}
function render(){let raw=(location.hash||'#home').replace(/^#/,'').split('?')[0];route=raw.split('/')[0];if(!ROUTES.some(r=>r[0]===route)&&route!=='lesson'&&route!=='field-detail')route='home';if(route==='lesson'){lessonId=raw.split('/')[1]||'seeing'}if(route==='field-detail'){activeField=raw.split('/')[1]||'hw15'}renderNavigation();const map={home,lessons,discover,lab,coach,field,exam,progress:progressPage,journal,settings};$('#page').innerHTML=route==='lesson'?lesson(D.lessons.find(x=>x.id===lessonId)):route==='field-detail'?fieldDetail(D.fields.find(x=>x.id===activeField)||D.fields[0]):(map[route]||home)();if(route==='lab')loadLab();window.scrollTo({top:0,behavior:'instant'});}
function getInput(id){return $('#'+id)?.value||''}
function addJournal(title,body,type='Journal'){state.journal.push({id:Date.now()+'-'+Math.random().toString(36).slice(2,6),title:String(title).slice(0,120),body:String(body).slice(0,5000),type,date:today()});save()}
function saveCoachAnswer(){let t=$('#coach-entry');if(t)coachAnswers[coachStep]=t.value.trim()}
function handle(action,el){switch(action){
case'open-coach':nav('coach');break;case'open-lab':nav('lab');break;case'lesson-open':nav('lesson/'+el.dataset.id);break;case'lesson-scene':sceneIndex=Number(el.dataset.n);hotIndex=-1;nav('discover');break;
case'complete-lesson':{let id=el.dataset.id;if(!state.done.includes(id))state.done.push(id);save();toast('Chapter recorded. Test the idea with a real photograph.');render();break}
case'save-lesson-note':state.notes[el.dataset.id]=getInput('lesson-note');save();toast('Your observation has been saved.');break;
case'lab-scene':labScene=Number(el.dataset.n);labImgSrc='';labReport=null;nav('lab');break;
case'scene-prev':sceneIndex=(sceneIndex-1+D.scenes.length)%D.scenes.length;hotIndex=-1;render();break;
case'scene-next':sceneIndex=(sceneIndex+1)%D.scenes.length;hotIndex=-1;render();break;
case'write-scene-note':modal('Your interpretation',`<p class="muted small">Use the scene as a prompt; we do not decide whether your interpretation is “correct”.</p><label class="field"><span>“The photograph is…”</span><input id="modal-title" maxlength="120" placeholder="One image idea" /></label><label class="field"><span>Why? Where would you stand? What would you remove?</span><textarea id="modal-body" maxlength="2500" placeholder="Your visual hypothesis"></textarea></label>${btn('Save to journal','modal-save-scene')}`);break;
case'modal-save-scene':{let t=getInput('modal-title').trim(),b=getInput('modal-body').trim();if(!t||!b){toast('Name your subject and explain your hypothesis.');break}addJournal(t,b,'Scene interpretation');$('#modal').innerHTML='';toast('Interpretation saved.');break}
case'lab-left':moveCrop(-.025,0);break;case'lab-right':moveCrop(.025,0);break;case'lab-up':moveCrop(0,-.025);break;case'lab-down':moveCrop(0,.025);break;case'lab-grid':labGrid=!labGrid;drawLab();el.textContent=labGrid?'▦ Grid on':'▦ Grid off';break;case'lab-reset':labCrop={x:.14,y:.14,w:.72,h:.72};labRatio='3:2';labReport=null;render();break;
case'lab-assess':assessLab();break;case'lab-save':saveLab();break;case'lab-export':exportLab();break;case'lab-own':if(state.photo){labImgSrc=state.photo;labReport=null;loadLabImage(labImgSrc);toast('Using your saved photograph.');}break;
case'lab-photo-remove':if(!confirm('Delete the locally saved practice photo?'))break;state.photo=null;save();labImgSrc='';render();break;
case'coach-prev':saveCoachAnswer();coachStep=clamp(coachStep-1,0,D.tips.length);render();break;case'coach-next':saveCoachAnswer();coachStep=clamp(coachStep+1,0,D.tips.length);render();break;case'coach-reset':coachStep=0;coachAnswers={};render();break;
case'coach-finish':{saveCoachAnswer();let summary=Object.entries(coachAnswers).filter(([k,v])=>v).map(([k,v])=>(Number(k)+1)+'. '+D.tips[k][0]+': '+v).join('\n');if(summary.length<15){toast('Record at least one concrete observation or reason before finishing.');break}addJournal('Scene recovery · '+date(today()),summary,'No-inspiration drill');state.coachDone.push({date:today(),notes:summary});save();coachStep=0;coachAnswers={};toast('Scene observation recorded.');nav('journal');break}
case'field-start':nav('field-detail/'+el.dataset.id);break;case'field-save':state.notes['field:'+el.dataset.id]=getInput('field-notes');save();toast('Field notes saved.');break;
case'field-complete':{let id=el.dataset.id,f=D.fields.find(x=>x.id===id),checks=A(state.fieldChecks[id]),notes=getInput('field-notes').trim();if(checks.length<f.steps.length){toast('Finish the mission checklist before logging a field session.');break}if(notes.length<40){toast('Add a meaningful field observation (at least 40 characters).');break}state.notes['field:'+id]=notes;state.fieldLogs.push({id,date:today(),notes});addJournal(f.title,notes,'Field session');save();toast('Your completed field session has been logged.');render();break}
case'go-journal':nav('journal');break;case'exam-start':state.examSession={index:0,answers:{},notes:{},started:today()};save();render();break;
case'exam-next':{let e=state.examSession;e.index++;save();render();break}
case'exam-note':{if(!state.examSession.notes)state.examSession.notes={};state.examSession.notes[el.dataset.qid]=getInput('quiz-note');save();toast('Observation saved.');break}
case'exam-finish':{let s=state.examSession,correct=D.questions.filter(q=>s.answers[q.id]===q.answer).length;state.exams.push({date:today(),score:correct,answers:s.answers});state.examSession=null;save();toast('Reasoning challenge saved.');render();break}
case'exam-restart':state.examSession={index:0,answers:{},notes:{},started:today()};save();render();break;
case'journal-new':modal('New observation',`<p class="small muted">One subject. One visual reason. One deliberate decision.</p><label class="field"><span>Title / photographic subject</span><input id="modal-title" maxlength="120" placeholder="The photograph is…" /></label><label class="field"><span>What did you see, change, reject or learn?</span><textarea id="modal-body" maxlength="3000" placeholder="Light, viewpoint, relationship, distractions, timing…"></textarea></label>${btn('Save journal entry','modal-save-journal')}`);break;
case'modal-save-journal':{let t=getInput('modal-title').trim(),b=getInput('modal-body').trim();if(!t||!b){toast('Add a title and observation first.');break}addJournal(t,b);$('#modal').innerHTML='';toast('Journal entry saved.');render();break}
case'modal-close':$('#modal').innerHTML='';break;
case'export-data':{let blob=new Blob([JSON.stringify({application:'Photographic Eye Lab',schema:1,exported:today(),data:state},null,2)],{type:'application/json'});downloadBlob(blob,'Photographic_Eye_Lab_progress_'+new Date().toISOString().slice(0,10)+'.json');break}
case'import-file':$('#backup-file')?.click();break;
case'clear-data':if(confirm('This erases ALL progress, notes and saved photo on this browser. Export a backup first if needed. Continue?')){state=blank();save();render();toast('Local records cleared.')}break;
case'offline-check':checkCache(true);break;case'offline-update':{if('serviceWorker'in navigator){navigator.serviceWorker.getRegistration().then(r=>{if(!r){toast('No service worker yet. Open the HTTPS site once online.');return}r.update().then(()=>toast('Offline asset update checked.')).catch(()=>toast('Could not check for an update while offline.'))});}break}
}}
function downloadBlob(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1200)}
function moveCrop(dx,dy){labCrop.x=clamp(labCrop.x+dx,0,1-labCrop.w);labCrop.y=clamp(labCrop.y+dy,0,1-labCrop.h);drawLab()}
function aspectNum(){return {'3:2':1.5,'4:5':.8,'1:1':1,'16:9':16/9}[labRatio]||1.5}
function updateCropZoom(zoom){const ar=aspectNum()/1.5;let w=1/zoom,h=w/ar;if(h>.96){h=.96;w=h*ar}labCrop.x=clamp(labCrop.x+(labCrop.w-w)/2,0,1-w);labCrop.y=clamp(labCrop.y+(labCrop.h-h)/2,0,1-h);labCrop.w=w;labCrop.h=h;drawLab();let o=$('#lab-zoom-value');if(o)o.textContent=(1/w).toFixed(2)+'×'}
function loadLab(){labImgSrc=labImgSrc||D.scenes[labScene].image;loadLabImage(labImgSrc);const canvas=$('#crop-canvas');if(canvas){canvas.addEventListener('pointerdown',e=>{let rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height;if(x>=labCrop.x&&x<=labCrop.x+labCrop.w&&y>=labCrop.y&&y<=labCrop.y+labCrop.h){labDrag={sx:x,sy:y,ox:labCrop.x,oy:labCrop.y};canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(!labDrag)return;let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;labCrop.x=clamp(labDrag.ox+x-labDrag.sx,0,1-labCrop.w);labCrop.y=clamp(labDrag.oy+y-labDrag.sy,0,1-labCrop.h);drawLab()});canvas.addEventListener('pointerup',()=>{labDrag=null});canvas.addEventListener('pointercancel',()=>{labDrag=null})}}
function loadLabImage(src){const img=new Image();img.onload=()=>{labImage=img;drawLab()};img.onerror=()=>{toast('Could not load this image.');labImage=null};img.src=src}
function drawLab(){let c=$('#crop-canvas');if(!c||!labImage)return;const ctx=c.getContext('2d'),W=c.width,H=c.height;ctx.clearRect(0,0,W,H);const iw=labImage.width,ih=labImage.height,ar=iw/ih,car=W/H;let dx=0,dy=0,dw=W,dh=H;if(ar>car){dw=H*ar;dx=(W-dw)/2}else{dh=W/ar;dy=(H-dh)/2}ctx.drawImage(labImage,dx,dy,dw,dh);let x=labCrop.x*W,y=labCrop.y*H,w=labCrop.w*W,h=labCrop.h*H;ctx.fillStyle='rgba(9,17,29,.63)';ctx.fillRect(0,0,W,y);ctx.fillRect(0,y,x,h);ctx.fillRect(x+w,y,W-x-w,h);ctx.fillRect(0,y+h,W,H-y-h);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(x,y,w,h);if(labGrid){ctx.strokeStyle='rgba(255,255,255,.64)';ctx.lineWidth=1;[1/3,2/3].forEach(q=>{ctx.beginPath();ctx.moveTo(x+w*q,y);ctx.lineTo(x+w*q,y+h);ctx.stroke();ctx.beginPath();ctx.moveTo(x,y+h*q);ctx.lineTo(x+w,y+h*q);ctx.stroke()})}ctx.fillStyle='#fff';ctx.font='bold 13px Arial';ctx.fillText('YOUR FRAME · DRAG TO MOVE',x+9,Math.max(18,y-10));ctx.strokeStyle='#fff';ctx.lineWidth=3;[[x,y],[x+w,y],[x,y+h],[x+w,y+h]].forEach(([px,py])=>{ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(px,py,6,0,Math.PI*2);ctx.fill()})}
function assessLab(){let subj=getInput('lab-subject').trim(),why=getInput('lab-why').trim(),excluded=getInput('lab-exclude').trim();const area=labCrop.w*labCrop.h;let points=[];if(!subj)points.push('Start with one precise subject: “The photograph is…”.');else points.push('You named a subject. Check whether it is visually obvious inside this crop.');if(!why)points.push('Identify the visual reason: light, isolation, leading line, relationship, repetition or timing.');else points.push('You recorded a reason to look. Now test it against a wider and a tighter alternative.');if(!excluded)points.push('State which distraction or excess context you removed and why.');else points.push('You named an exclusion. Check that you did not remove essential context as well.');if(area>.75)points.push('This crop includes most of the source. Consider whether a smaller frame would strengthen hierarchy.');if(area<.10)points.push('This is a very tight crop. Verify that enough context remains and that image resolution supports it.');points.push('A crop cannot simulate a changed camera station. Test the viewpoint on location.');const html=`<div class="coach-output mt12"><strong>Structural feedback · not an artistic score</strong><ul>${points.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`;$('#lab-assessment').innerHTML=html;labReport={subject:subj,why,excluded,assessment:html}}
function saveLab(){assessLab();if(!labReport.subject||!labReport.why||!labReport.excluded){toast('Identify your subject, why it matters and what you excluded first.');return}let study={id:Date.now(),date:today(),scene:labImgSrc.startsWith('data:')?'Own photograph':D.scenes[labScene].title,subject:labReport.subject,why:labReport.why,excluded:labReport.excluded,ratio:labRatio,crop:{...labCrop}};state.studies.push(study);save();toast('Composition study saved with its reasoning.')}
function exportLab(){if(!labImage){toast('No image loaded.');return}let t=document.createElement('canvas');let iw=labImage.naturalWidth,ih=labImage.naturalHeight,W=960,H=640,ar=iw/ih,car=W/H,dx=0,dy=0,dw=W,dh=H;if(ar>car){dw=H*ar;dx=(W-dw)/2}else{dh=W/ar;dy=(H-dh)/2}let sx=(labCrop.x*W-dx)/dw*iw,sy=(labCrop.y*H-dy)/dh*ih,sw=labCrop.w*W/dw*iw,sh=labCrop.h*H/dh*ih;t.width=Math.max(1,Math.round(sw));t.height=Math.max(1,Math.round(sh));let ctx=t.getContext('2d');ctx.drawImage(labImage,sx,sy,sw,sh,0,0,t.width,t.height);t.toBlob(b=>{if(b)downloadBlob(b,'Photographic_Eye_Lab_crop.jpg');else toast('Could not export this crop.')},'image/jpeg',.93)}
function compressPhoto(file){const reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{let c=document.createElement('canvas');let w=im.width,h=im.height,s=Math.min(1,1400/Math.max(w,h));c.width=Math.round(w*s);c.height=Math.round(h*s);c.getContext('2d').drawImage(im,0,0,c.width,c.height);let value=c.toDataURL('image/jpeg',.80);state.photo=value;if(save()){labImgSrc=value;loadLabImage(value);toast('Photo stored privately in this browser for offline practice.');render()}else{state.photo=null}};im.onerror=()=>toast('This browser could not decode that image. Try JPEG.');im.src=reader.result};reader.onerror=()=>toast('Could not read the photo.');reader.readAsDataURL(file)}
function checkCache(show){let e=$('#cache-status');if(!('serviceWorker'in navigator)){if(e)e.textContent='Standalone/browser mode';if(show)toast('Offline install needs HTTPS or localhost; local HTML works without a server.');return}navigator.serviceWorker.getRegistration().then(r=>{let active=Boolean(r?.active);if(e){e.innerHTML='<i></i> '+(active?'Offline app installed':'Offline files preparing');e.classList.toggle('ready',active)}if(show)toast(active?'Offline app installed. Disconnect and reopen to verify locally.':'Offline cache is not yet active; open the site while online.')}).catch(()=>{if(show)toast('Offline status unavailable.')})}
function attach(){document.addEventListener('click',e=>{let navEl=e.target.closest('[data-route]');if(navEl){let to=navEl.dataset.route;menuOpen=false;nav(to);return}let se=e.target.closest('[data-scene]');if(se){sceneIndex=Number(se.dataset.scene);hotIndex=-1;nav('discover');return}let hot=e.target.closest('[data-hot]');if(hot){let s=D.scenes[sceneIndex];hotIndex=Number(hot.dataset.hot);if(!state.found[s.id])state.found[s.id]=[];if(!state.found[s.id].includes(hotIndex))state.found[s.id].push(hotIndex);save();render();return}let ls=e.target.closest('[data-lab-scene]');if(ls){labScene=Number(ls.dataset.labScene);labImgSrc=D.scenes[labScene].image;labReport=null;render();return}let rat=e.target.closest('[data-ratio]');if(rat){labRatio=rat.dataset.ratio;const newW=labCrop.w,h=newW/(aspectNum()/1.5);updateCropZoom(1/Math.min(.94,newW));$$('[data-ratio]').forEach(x=>x.classList.toggle('active',x.dataset.ratio===labRatio));return}let q=e.target.closest('[data-qanswer]');if(q&&state.examSession){let s=state.examSession,key=D.questions[s.index].id;if(s.answers[key]!==undefined)return;s.answers[key]=Number(q.dataset.qanswer);save();render();return}let del=e.target.closest('[data-journal-delete]');if(del){let id=del.dataset.journalDelete;if(confirm('Delete this journal entry from this device?')){state.journal=state.journal.filter(x=>x.id!==id);save();render()}return}let action=e.target.closest('[data-action]');if(action){handle(action.dataset.action,action);return}});
document.addEventListener('change',e=>{let c=e.target;if(c.matches('[data-fieldcheck]')){let id=c.dataset.fieldid,n=Number(c.dataset.fieldcheck);let v=A(state.fieldChecks[id]);state.fieldChecks[id]=c.checked?[...new Set([...v,n])]:v.filter(x=>x!==n);save();let bar=$('.progress-bar span');if(bar)bar.style.width=Math.round(100*state.fieldChecks[id].length/D.fields.find(f=>f.id===id).steps.length)+'%'}else if(c.id==='photo-upload'&&c.files?.[0]){if(c.files[0].size>18*1024*1024){toast('For large photos, export a JPEG copy below 18 MB first.');return}compressPhoto(c.files[0])}else if(c.id==='backup-file'&&c.files?.[0]){let f=c.files[0];if(f.size>15*1024*1024){toast('Backup file too large.');return}let reader=new FileReader();reader.onload=()=>{try{let v=JSON.parse(reader.result);if(v.application!=='Photographic Eye Lab'||v.schema!==1||!v.data||!Array.isArray(v.data.done)||!Array.isArray(v.data.journal))throw Error('Invalid backup format');if(!confirm('Replace this browser’s existing Photographic Eye Lab record with the backup?'))return;state={...blank(),...v.data};save();render();toast('Backup imported.')}catch{toast('This is not a valid Photographic Eye Lab backup.')}};reader.readAsText(f)}});
document.addEventListener('input',e=>{if(e.target.id==='lab-zoom')updateCropZoom(Number(e.target.value))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modal').innerHTML='';menuOpen=false;$('#sidebar').classList.remove('open')}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-route]')){e.preventDefault();nav(e.target.dataset.route)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-scene]')){e.preventDefault();sceneIndex=Number(e.target.dataset.scene);nav('discover')}});
$('#menu-toggle').addEventListener('click',()=>{menuOpen=!menuOpen;$('#sidebar').classList.toggle('open',menuOpen)});$('#quick-discover').addEventListener('click',()=>nav('coach'));window.addEventListener('hashchange',render);}
function initSW(){if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){navigator.serviceWorker.register('./sw.js').then(()=>checkCache()).catch(()=>checkCache())}else{let e=$('#cache-status');if(e)e.innerHTML='<i></i> Standalone file mode'}navigator.serviceWorker?.addEventListener('controllerchange',()=>{checkCache();toast('Offline app updated. Refresh when convenient.')})}
attach();let first=(location.hash||'#home').slice(1).split('/')[0];route=ROUTES.some(x=>x[0]===first)||['lesson','field-detail'].includes(first)?first:'home';render();initSW();
})();
